// Clean Supabase service without any verification references
import { authService, supabase } from './authentication';

// Re-export auth service
export { authService };
export { supabase };

// Clean services without verification
export const categoriesService = {
  async getCategories() {
    try {
      const { data, error } = await supabase
        .from('categories')
        .select('*')
        .eq('active', true)
        .order('sort_order');

      if (error) throw error;
      return data || [];
    } catch (error) {
      console.log('Categories not available');
      return [];
    }
  }
};

export const tasksService = {
  async getTasks(filters = {}) {
    try {
      let query = supabase
        .from('tasks')
        .select(`
          *,
          categories(name, color, icon),
          users!tasks_employer_id_fkey(full_name, rating, avatar_url),
          task_submissions(id, status, worker_id)
        `)
        .eq('status', 'active');

      // Apply filters
      if (filters.category) {
        query = query.eq('category_id', filters.category);
      }
      if (filters.search) {
        query = query.or(`title.ilike.%${filters.search}%,description.ilike.%${filters.search}%`);
      }
      if (filters.minReward) {
        query = query.gte('reward_amount', filters.minReward);
      }
      if (filters.maxReward) {
        query = query.lte('reward_amount', filters.maxReward);
      }
      if (filters.difficulty) {
        query = query.eq('difficulty_level', filters.difficulty);
      }

      const { data, error } = await query
        .order('created_at', { ascending: false })
        .limit(filters.limit || 20);

      if (error) throw error;
      return data || [];
    } catch (error) {
      console.error('Error fetching tasks:', error);
      return [];
    }
  },

  async getTaskById(taskId) {
    try {
      const { data, error } = await supabase
        .from('tasks')
        .select(`
          *,
          categories(name, color, icon),
          users!tasks_employer_id_fkey(full_name, rating, avatar_url, company),
          task_submissions(
            id, 
            submission_text, 
            submission_files, 
            status, 
            rating, 
            feedback,
            submitted_at,
            users!task_submissions_worker_id_fkey(full_name, avatar_url, rating)
          )
        `)
        .eq('id', taskId)
        .single();

      if (error) throw error;
      return data;
    } catch (error) {
      console.error('Error fetching task:', error);
      throw error;
    }
  },

  async createTask(taskData) {
    try {
      const { data, error } = await supabase
        .from('tasks')
        .insert([{
          title: taskData.title,
          description: taskData.description,
          employer_id: taskData.employer_id,
          category_id: taskData.category_id,
          reward_amount: taskData.reward_amount,
          deadline: taskData.deadline,
          difficulty_level: taskData.difficulty_level || 'medium',
          required_skills: taskData.required_skills || [],
          attachments: taskData.attachments || [],
          deliverables: taskData.deliverables || [],
          max_submissions: taskData.max_submissions || 1,
          allow_revisions: taskData.allow_revisions !== false,
          status: 'active'
        }])
        .select()
        .single();

      if (error) throw error;
      return data;
    } catch (error) {
      console.error('Error creating task:', error);
      throw error;
    }
  },

  async updateTask(taskId, updates) {
    try {
      const { data, error } = await supabase
        .from('tasks')
        .update({
          ...updates,
          updated_at: new Date().toISOString()
        })
        .eq('id', taskId)
        .select()
        .single();

      if (error) throw error;
      return data;
    } catch (error) {
      console.error('Error updating task:', error);
      throw error;
    }
  },

  async deleteTask(taskId) {
    try {
      const { error } = await supabase
        .from('tasks')
        .delete()
        .eq('id', taskId);

      if (error) throw error;
      return true;
    } catch (error) {
      console.error('Error deleting task:', error);
      throw error;
    }
  },

  async getUserTasks(userId) {
    try {
      const { data, error } = await supabase
        .from('tasks')
        .select(`
          *,
          categories(name, color, icon),
          task_submissions(
            id, 
            status, 
            submitted_at,
            users!task_submissions_worker_id_fkey(full_name, avatar_url)
          )
        `)
        .eq('employer_id', userId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      return data || [];
    } catch (error) {
      console.error('Error fetching user tasks:', error);
      return [];
    }
  }
};

export const usersService = {
  async getProfile(userId) {
    return await authService.getProfile(userId);
  },

  async updateProfile(userId, updates) {
    return await authService.updateProfile(userId, updates);
  },

  async getWalletBalance(userId) {
    console.log('Wallet balance not implemented yet');
    return 0;
  }
};

// Placeholder services
export const fileService = {
  async uploadFile(file, bucket = 'task-files', folder = '') {
    console.log('File upload not implemented yet');
    // Return mock data to prevent errors
    return {
      data: {
        path: `${folder}/${file.name}`,
        publicUrl: `https://placeholder.com/${file.name}`
      }
    };
  }
};

// Removed subscription service - no longer needed for pricing

export const transactionsService = {
  async getUserTransactions(userId) { 
    console.log('Get user transactions not implemented yet');
    return []; 
  }
};

export const paymentService = {
  async processPayment() { 
    console.log('Process payment not implemented yet');
    return { success: false }; 
  },

  async submitWithdrawalRequest(userId, amount, paymentMethodId, documents) {
    console.log('Submit withdrawal request not implemented yet');
    return { id: Date.now(), userId, amount, status: 'pending' };
  },

  async getPaymentMethods(userId) {
    console.log('Get payment methods not implemented yet');
    return [];
  },

  async addPaymentMethod(userId, methodData) {
    console.log('Add payment method not implemented yet');
    return { id: Date.now(), userId, ...methodData };
  }
};

export const submissionsService = {
  async getUserSubmissions(userId) { 
    console.log('Get user submissions not implemented yet');
    return []; 
  },

  async submitTask(taskId, submissionData) {
    console.log('Submit task not implemented yet');
    return { id: Date.now(), taskId, ...submissionData };
  },

  async updateSubmissionStatus(submissionId, status, feedback, rating) {
    console.log('Update submission status not implemented yet');
    return { id: submissionId, status, feedback, rating };
  }
};

export const notificationService = {
  async getUserNotifications(userId) { 
    console.log('Notifications not implemented yet');
    return []; 
  },
  async markAsRead(notificationId) {
    console.log('Mark as read not implemented yet');
    return true;
  },
  async createNotification(userId, title, message, type, referenceId, referenceType) {
    console.log('Create notification not implemented yet');
    return { id: Date.now(), userId, title, message, type };
  }
};

export const realtimeService = {
  subscribeToNotifications(userId, callback) {
    console.log('Real-time notifications not implemented yet');
    return {
      unsubscribe: () => console.log('Unsubscribed from notifications')
    };
  },
  subscribeToTasks(callback) {
    console.log('Real-time tasks not implemented yet');
    return {
      unsubscribe: () => console.log('Unsubscribed from tasks')
    };
  }
};
export const analyticsService = {
  async trackEvent(eventName, properties = {}) {
    console.log('Analytics:', eventName, properties);
  },
  async trackPageView(pageName, properties = {}) {
    console.log('Page View:', pageName, properties);
  },
  async trackTaskInteraction(action, taskId, properties = {}) {
    console.log('Task Interaction:', action, taskId, properties);
  }
};

export default supabase;
